insert into public.pages
  (slug, title, content_md, cover_image, meta_description, sort_order, is_published)
values
  (E'gimnasio', E'Γυμνάσιο', E'## Πρόγραμμα Σπουδών Γυμνασίου\n\n# Α Γυμνασίου\n\nΗ Α΄ Γυμνασίου σηματοδοτεί τη μετάβαση του παιδιού από την πρωτοβάθμια στη δευτεροβάθμια εκπαίδευση. Είναι ιδιαίτερα σημαντικό η μετάβαση αυτή να είναι ομαλή και επιτυχημένη. Αν ένα παιδί στο ξεκίνημά του βιώσει την επιτυχία αυτό θα του δώσει το κίνητρο για περαιτέρω προσπάθεια να συνεχίσει δυναμικά και στις υπόλοιπες τάξεις φτάνοντας έτσι στην ΚΟΡΥΦΗ.\n\nΜάθημα |  Ώρες\n---|---\nΑρχαία Ελληνική Γλώσσα και Γραμματεία  |  2\nΝέα Ελληνική Γλώσσα και Γραμματεία |  2\nΜαθηματικά |  2\nΦυσική |  1\n**Σύνολο** |  **7**\n\n#### Β Γυμνασίου\n\nΠρόκειται για την τάξη όπου ο μαθητής συνεχίζει με την ύλη που διδάχτηκε την προηγούμενη χρονιά σε Νεοελληνική Γλώσσα και Γραμματεία, Αρχαία ελληνική Γλώσσα και Γραμματεία και Μαθηματικά και θα έρθει σε επαφή με δυο καινούρια μαθήματα , τη φυσική και τη χημεία.\n\nΜάθημα |  Ώρες\n---|---\nΑρχαία Ελληνική Γλώσσα και Γραμματεία  |  2\nΝέα Ελληνική Γλώσσα και Γραμματεία |  2\nΜαθηματικά |  2\nΦυσική |  1\nΧημεία |  1\n**Σύνολο** |  **8**\n\n#### Γ Γυμνασίου\n\nΗ Γ΄ Γυμνασίου είναι η πιο απαιτητική τάξη του γυμνασίου. Στόχος αυτής της τάξης είναι αφενός να κατακτήσουν οι μαθητές την ύλη της Γ΄ Γυμνασίου στο σύνολό της και αφετέρου να μην έχουν κανένα κενό από τις προηγούμενες τάξεις του γυμνασίου, προκειμένου να γίνει η μετάβασή τους στο λύκειο με τον καλύτερο δυνατό τρόπο.\n\nΜάθημα |  Ώρες\n---|---\nΑρχαία Ελληνική Γλώσσα και Γραμματεία  |  2\nΝέα Ελληνική Γλώσσα και Γραμματεία |  2\nΜαθηματικά |  2\nΦυσική |  1\nΧημεία |  1\n**Σύνολο** |  **8**', NULL, E'Μαθήματα Γυμνασίου με μικρά τμήματα και προσωπική παρακολούθηση. Στέρεες βάσεις για το Λύκειο, στην Κορυφή της Καλλονής.', 10, true),
  (E'alikeiou', E'Α'' Λυκείου', E'## Πρόγραμμα Σπουδών A Τάξης Γενικού Λυκείου\n\n#### Α Λυκείου\n\nΗ Α΄ Λυκείου σηματοδοτεί τη μετάβαση του παιδιού από το Γυμνάσιο στο Λύκειο και την προετοιμασία του για τις Πανελλαδικές Εξετάσεις της Γ'' Λυκείου. Σε αυτή την τάξη πρέπει να καλύψει τα κενά των γνώσεων του από το Γυμνάσιο για να μπορέσει να επιτύχει στις Πανελλαδικές Εξετάσεις.\n\nΜάθημα |  Ώρες\n---|---\nΆλγεβρα |  3\nΓεωμετρία |  1\nΦυσική |  2\nΧημεία |  2\nΒιολογία |  1\nΑρχαία Ελληνική Γλώσσα |  2\nΈκφραση Έκθεση |  2\n**Σύνολο** |  **13**\n\n## Τα μαθήματα προετοιμασίας για τις Πανελλαδικές Εξετάσεις θα γίνουν σε συνεννόηση με τον Διδάσκοντα Καθηγητή.', NULL, E'Μαθήματα Α'' Λυκείου με μικρά τμήματα έως 5 μαθητές. Σταθερές βάσεις σε όλα τα μαθήματα προσανατολισμού στην Κορυφή της Καλλονής.', 20, true),
  (E'blikeiou', E'Β'' Λυκείου', E'## Πρόγραμμα Σπουδών Β Τάξης Γενικού Λυκείου\n\n#### Β Λυκείου\n\nΗ Β΄ Λυκείου σηματοδοτεί την προετοιμασία του μαθητή για τις Πανελλαδικές Εξετάσεις της Γ'' Λυκείου. Σε αυτήν την τάξη πρέπει να ξεκινήσει την προετοιμασία για την επόμενη σχολική χρονιά για να μπορέσει να επιτύχει στις Πανελλαδικές Εξετάσεις.\n\nΜάθημα |  Ώρες\n---|---\nΆλγεβρα |  3\nΓεωμετρία |  1\nΜαθηματικά Κατεύθυνσης |  1\nΦυσική |  4\nΧημεία |  2\nΒιολογία |  1\nΑρχαία Ελληνική Γλώσσα |  2\nΈκφραση Έκθεση |  2\nΑρχές Οικονομικής Θεωρίας(Προετοιμασία Πανελληνίων*) |  2\nΑνάπτυξη Εφαρμογών σε Προγραμματιστικό Περιβάλλον Γ'' Λυκείου (Προετοιμασία Πανελληνίων*) |  2\n**Σύνολο** |  **-**\n\n* Τα μαθήματα προετοιμασίας για τις Πανελλαδικές Εξετάσεις θα γίνουν σε συνεννόηση με τον Διδάσκοντα Καθηγητή. * Επικοινωνήστε μαζί μας για διευκρινήσεις σχετικά με τα μαθήματα και τις κατευθύνσεις καθώς είναι διαφορετικά τα μαθήματα που πρέπει να παρακολουθήσει ενας μαθητής/τρια θετικής κατεύθυνσης από έναν/μια θεωρητικής.', NULL, E'Μαθήματα Β'' Λυκείου με στόχο τις κατευθύνσεις και την προετοιμασία για Πανελλήνιες. Τμήματα έως 5 μαθητές, στην Καλλονή ή online.', 30, true),
  (E'glikeiou', E'Γ'' Λυκείου & Πανελλήνιες', E'## Πρόγραμμα Σπουδών Γ Τάξης Γενικού Λυκείου\n\n#### Γ Λυκείου\n\nΗ Γ΄ Λυκείου είναι η χρονιά των Πανελλαδικών εξετάσεων που θα καθορίσουν την είσοδο του μαθητή στην τριτοβάθμια εκπαίδευση και αποτελεί την καθοριστικότερη χρονιά της δευτεροβάθμιας εκπαίδευσης. Οι έμπειροι καθηγητές των Φροντιστηρίων μέσης εκπαίδευσης ΚΟΡΥΦΗ θα βοηθήσουν τον μαθητή να επιτύχει τους στόχους του μέσα απο την εντατική ενασχόληση το δίαβασμα και τις προσομοιώσεις για τις εξετάσεις.\n\n#### Σύστημα Πανελλαδικών Εξετάσεων\n\n## Το νέο σύστημα των πανελλαδικών Εξετάσεων χωρίζει τις σχολές σε 4 επιστημονικά πεδία:\n\n#### 1ο Επιστημονικό Πεδίο\n\nΑνθρωπιστικών, Νομικών και Κοινωνικών Επιστημών με εξεταστέα μαθήματα:\nΑρχαία\nΝεοελληνική Γλώσσα και Λογοτεχνία\nΙστορία\nΛατινικά.\n\nΜάθημα |  Ώρες\n---|---\nΝεοελληνική Γλώσσα και Λογοτεχνία |  3\nΑρχαία |  4\nΙστορία |  2\nΛατινικά |  2\n**Σύνολο Ωρών/Εβδομάδα** |  **11**\n**Σύνολο Ωρών/Μήνα** |  **44**\n\nΟι ώρες ανα εβδομάδα είναι ενδεικτικές και θα τροποποιηθούν ανάλογα με τις ανάγκες του κάθε τμήματος κατόπιν συνεννοήσεως με τον Καθηγητή.\n\n#### 2o Επιστημονικό Πεδίο\n\n## Θετικών και Τεχνολογικών Επιστημών με εξεταστέα μαθήματα:\nΜαθηματικά\nΦυσική\nΧημεία\nΝεοελληνική Γλώσσα και Λογοτεχνία\n\nΜάθημα |  Ώρες\n---|---\nΝεοελληνική Γλώσσα και Λογοτεχνία |  3\nΜαθηματικά |  5\nΦυσική |  4\nΧημεία |  5\n**Σύνολο Ωρών/Εβδομάδα** |  **17**\n**Σύνολο Ωρών/Μήνα** |  **68**\n\nΟι ώρες ανα εβδομάδα είναι ενδεικτικές και θα τροποποιηθούν ανάλογα με τις ανάγκες του κάθε τμήματος κατόπιν συνεννοήσεως με τον Καθηγητή.\n\n#### 3o Επιστημονικό Πεδίο\n\n## Επιστημών Υγείας και Ζωής με εξεταστέα μαθήματα:\nΒιολογία\nΦυσική\nΧημεία\nΝεοελληνική Γλώσσα και Λογοτεχνία\n\nΜάθημα |  Ώρες\n---|---\nΝεοελληνική Γλώσσα και Λογοτεχνία |  3\nΧημεία |  5\nΦυσική |  4\nΒιολογία |  3\n**Σύνολο Ωρών/Εβδομάδα** |  **15**\n**Σύνολο Ωρών/Μήνα** |  **60**\n\nΟι ώρες ανα εβδομάδα είναι ενδεικτικές και θα τροποποιηθούν ανάλογα με τις ανάγκες του κάθε τμήματος κατόπιν συνεννοήσεως με τον Καθηγητή.\n\n#### 4o Επιστημονικό Πεδίο\n\nΕπιστημών Οικονομίας και Πληροφορικής με εξεταστέα μαθήματα:\nΜαθηματικά\nΑρχές Οικονομικής Θεωρίας\nΑνάπτυξη Εφαρμογών σε Προγραμματιστικό Περειβάλλον (ΑΕΠΠ)\nΝεοελληνική Γλώσσα και Λογοτεχνία\n\nΜάθημα |  Ώρες\n---|---\nΝεοελληνική Γλώσσα και Λογοτεχνία |  3\nΜαθηματικά |  5\nΑρχές Οικονομικής Θεωρίας |  2\nΑνάπτυξη Εφαρμογών σε Προγραμματιστικό Περιβάλλον |  3\n**Σύνολο Ωρών/Εβδομάδα** |  **13**\n**Σύνολο Ωρών/Μήνα** |  **52**\n\nΟι ώρες ανα εβδομάδα είναι ενδεικτικές και θα τροποποιηθούν ανάλογα με τις ανάγκες του κάθε τμήματος κατόπιν συνεννοήσεως με τον Καθηγητή.', NULL, E'Στοχευμένη προετοιμασία για Πανελλήνιες. Μικρά τμήματα έως 5 μαθητές, υβριδική διδασκαλία και πρόσβαση στον Οδηγό Σταδιοδρομίας.', 40, true),
  (E'epal', E'ΕΠΑΛ', E'## Πρόγραμμα Σπουδών ΕΠΑΛ 2020​\n\n#### Α'' ΕΠΑΛ\n\nΑ Τάξη ΕΠΑ.Λ.: Είναι Τάξη Βασικών Δεξιοτήτων, δηλαδή αποκτώνται γενικές γνώσεις και δεξιότητες και περιλαμβάνει κοινά μαθήματα για όλους τους μαθητές. Διδάσκονται μαθήματα Γενικής Παιδείας (22 ώρες), μαθήματα Προσανατολισμού (7 ώρες), 3 μαθήματα Επιλογής (6 ώρες) . Σύνολο: 35\n\nΜάθημα |  Ώρες\n---|---\nΑρχαία Ελληνική Γλώσσα και Γραμματεία |  2\nΝέα Ελληνική Γλώσσα και Γραμματεία |  2\nΜαθηματικά |  3\nΦυσική |  3\nΧημεία |  3\n**Σύνολο** |  **13**\n\n#### Β'' ΕΠΑΛ\n\nΒ Τάξη ΕΠΑ.Λ.: Είναι τάξη Επαγγελματικών Τομέων και διαχωρίζεται σε τομείς σπουδών. Προαχθέντες μαθητές της Α΄ Τάξης εντάσσονται με αίτησή τους σε όποιο τομέα της Β’ Τάξης επιθυμούν. Διδάσκονται μαθήματα Γενικής Παιδείας (12 ώρες) κοινά για όλους τους μαθητές και μαθήματα Επαγγελματικών Τομέων (θεωρητικά και εργαστηριακά) (23 ώρες). Σύνολο: 35\n\nOι μαθητές στη Β΄ τάξη των Επαγγελματικών Λυκείων θα επιλέξουν έναν από τους παρακάτω 9 Τομείς:\n\n#### 1oς Τομέας Γεωπονίας, Τροφίμων και Περιβάλλοντος\n\n(α) Τεχνικός Φυτικής Παραγωγής\n(β) Τεχνικός Ζωικής Παραγωγής\n(γ) Τεχνικός Τεχνολογίας Τροφίμων και Ποτών\n(δ) Τεχνικός Ανθοκομίας και Αρχιτεκτονικής Τοπίου\n\n#### 2oς Τομέας Διοίκησης και Οικονομίας\n\n(α) Υπάλληλος Διοίκησης και Οικονομικών Υπηρεσιών\n(β) Υπάλληλος Τουριστικών Επιχειρήσεων\n(γ) Υπάλληλος Εμπορίας και Διαφήμισης\n(δ) Υπάλληλος Αποθήκης και Συστημάτων Εφοδιασμού\n\n#### 3oς Τομέας Δομικών Έργων, Δομημένου Περιβάλλοντος και Αρχιτεκτονικού Σχεδιασμού\n\n## Τεχνικός Δομικών Έργων και Γεωπληροφορικής\n\n#### 4oς Τομέας Εφαρμοσμένων Τεχνών\n\n(α) Γραφικών Τεχνών\n(β) Αργυροχρυσοχοΐας\n(γ) Συντήρησης Έργων Τέχνης – Αποκατάστασης\n(δ) Σχεδίασης και Παραγωγής Ενδύματος\n(ε) Σχεδιασμού-Διακόσμησης Εσωτερικών Χώρων\n(στ) Επιπλοποιίας –Ξυλογλυπτικής\n\n#### 5oς Τομέας Ηλεκτρολογίας, Ηλεκτρονικής και Αυτοματισμού\n\n(α) Τεχνικός Ηλεκτρονικών και Υπολογιστικών Συστημάτων, Εγκαταστάσεων, Δικτύων και Τηλεπικοινωνιών\n(β) Τεχνικός Ηλεκτρολογικών Συστημάτων, Εγκαταστάσεων και Δικτύων\n(γ) Τεχνικός Αυτοματισμού\n\n#### 6oς Τομέας Τομέας Μηχανολογίας\n\n(α) Τεχνικός Μηχανολογικών Εγκαταστάσεων και Κατασκευών\n(β) Τεχνικός Θερμικών και Υδραυλικών Εγκαταστάσεων και Τεχνολογίας Πετρελαίου και Φυσικού Αερίου\n(γ) Τεχνικός Εγκαταστάσεων Ψύξης Αερισμού και Κλιματισμού\n(δ) Τεχνικός Οχημάτων,(ε) Τεχνικός Μηχανοσυνθέτης Αεροσκαφών\n\n#### 7oς Τομέας Ναυτιλιακών Επαγγελμάτων\n\n## (α) Πλοίαρχος Εμπορικού Ναυτικού\n(β) Μηχανικός Εμπορικού Ναυτικού\n\n#### 8oς Τομέας Πληροφορικής\n\n## (α) Τεχνικός Εφαρμογών Πληροφορικής\n(β) Τεχνικός Η/Υ και Δικτύων Η/Υ\n\n#### 9oς Τομέας Υγείας - Πρόνοιας - Ευεξίας\n\n#### Γ'' ΕΠΑΛ\n\nΓ Τάξη ΕΠΑ.Λ.: Είναι τάξη Επαγγελματικών Ειδικοτήτων και διαχωρίζεται σε ειδικότητες. Προαχθέντες μαθητές της Β΄ Τάξης εντάσσονται με αίτησή τους σε οποιαδήποτε ειδικότητα του τομέα που παρακολούθησαν. Διδάσκονται μαθήματα Γενικής Παιδείας (12 ώρες) κοινά για όλους τους μαθητές και μαθήματα Ειδικότητας (θεωρητικά και εργαστηριακά) (23 ώρες) Σύνολο: 35\n\nΜάθημα |  Ώρες\n---|---\nΈκθεση και Λογοτεχνία |  2\nΜαθηματικά |  3\n1ο μάθημα ειδικότητας |  2\n2ο μάθημα ειδικότητας |  2\n**Σύνολο** |  **9**', NULL, E'Πλήρης υποστήριξη για όλους τους τομείς ΕΠΑΛ και τις Πανελλαδικές. Μικρά τμήματα, υβριδική διδασκαλία, εξειδικευμένοι καθηγητές.', 50, true)
on conflict (slug) do update set
  title            = excluded.title,
  content_md       = excluded.content_md,
  cover_image      = excluded.cover_image,
  meta_description = excluded.meta_description,
  sort_order       = excluded.sort_order,
  is_published     = excluded.is_published,
  updated_at       = now();